"""Map Sigma rules to MITRE ATT&CK using standard ``attack.*`` tags."""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Iterable, Mapping, Sequence

import yaml

from .catalog import AttackCatalog, get_catalog, normalize_technique


ATTACK_PREFIX = "attack."
SOFTWARE_PATTERN = re.compile(r"^s\d{4}$", re.IGNORECASE)
GROUP_PATTERN = re.compile(r"^g\d{4}$", re.IGNORECASE)
DATA_SOURCE_PATTERN = re.compile(r"^ds\d{4}$", re.IGNORECASE)
MITIGATION_PATTERN = re.compile(r"^m\d{4}$", re.IGNORECASE)
CAMPAIGN_PATTERN = re.compile(r"^c\d{4}$", re.IGNORECASE)


class RuleMappingError(ValueError):
    """Raised when a Sigma rule cannot be loaded or mapped."""


@dataclass(frozen=True)
class AttackMapping:
    """ATT&CK entities referenced by one Sigma rule."""

    rule_id: str | None
    title: str
    path: str | None
    tags: tuple[str, ...] = ()
    techniques: tuple[str, ...] = ()
    explicit_tactics: tuple[str, ...] = ()
    tactics: tuple[str, ...] = ()
    software: tuple[str, ...] = ()
    groups: tuple[str, ...] = ()
    data_sources: tuple[str, ...] = ()
    mitigations: tuple[str, ...] = ()
    campaigns: tuple[str, ...] = ()
    unknown_techniques: tuple[str, ...] = ()
    unknown_attack_tags: tuple[str, ...] = ()

    @property
    def is_mapped(self) -> bool:
        return bool(self.techniques or self.tactics)

    @property
    def has_technique(self) -> bool:
        return bool(self.techniques)

    def rule_ref(self) -> dict[str, str | None]:
        return {"id": self.rule_id, "title": self.title, "path": self.path}

    def to_dict(self) -> dict[str, Any]:
        return {
            "id": self.rule_id,
            "title": self.title,
            "path": self.path,
            "tags": list(self.tags),
            "techniques": list(self.techniques),
            "explicit_tactics": list(self.explicit_tactics),
            "tactics": list(self.tactics),
            "software": list(self.software),
            "groups": list(self.groups),
            "data_sources": list(self.data_sources),
            "mitigations": list(self.mitigations),
            "campaigns": list(self.campaigns),
            "unknown_techniques": list(self.unknown_techniques),
            "unknown_attack_tags": list(self.unknown_attack_tags),
            "mapped": self.is_mapped,
        }


def _tag_strings(tags: Any) -> Iterable[str]:
    if tags is None:
        return
    if isinstance(tags, str):
        tags = [tags]
    for tag in tags:
        if isinstance(tag, str):
            yield tag
        elif hasattr(tag, "namespace") and hasattr(tag, "name"):
            # pySigma SigmaRuleTag
            yield f"{tag.namespace}.{tag.name}"
        else:
            text = str(tag)
            if text and text != repr(tag):
                yield text


@dataclass
class _ParsedTags:
    techniques: set[str] = field(default_factory=set)
    explicit_tactics: set[str] = field(default_factory=set)
    software: set[str] = field(default_factory=set)
    groups: set[str] = field(default_factory=set)
    data_sources: set[str] = field(default_factory=set)
    mitigations: set[str] = field(default_factory=set)
    campaigns: set[str] = field(default_factory=set)
    unknown_techniques: set[str] = field(default_factory=set)
    unknown_attack_tags: set[str] = field(default_factory=set)


def parse_attack_tags(tags: Any, catalog: AttackCatalog | None = None) -> _ParsedTags:
    """Parse standard Sigma ATT&CK tags.

    The parser accepts both strings and pySigma ``SigmaRuleTag`` objects. Only
    the ``attack`` namespace is interpreted; all other tags are left untouched.
    """

    catalog = catalog or get_catalog()
    parsed = _ParsedTags()
    for raw_tag in _tag_strings(tags):
        tag = raw_tag.strip()
        if not tag.lower().startswith(ATTACK_PREFIX):
            continue
        value = tag[len(ATTACK_PREFIX) :].strip().lower()
        if not value:
            parsed.unknown_attack_tags.add(value)
            continue
        technique_id = normalize_technique(value)
        if technique_id is not None:
            parsed.techniques.add(technique_id)
            if not catalog.is_known_technique(technique_id):
                parsed.unknown_techniques.add(technique_id)
            continue
        if SOFTWARE_PATTERN.fullmatch(value):
            parsed.software.add(value.upper())
        elif GROUP_PATTERN.fullmatch(value):
            parsed.groups.add(value.upper())
        elif DATA_SOURCE_PATTERN.fullmatch(value):
            parsed.data_sources.add(value.upper())
        elif MITIGATION_PATTERN.fullmatch(value):
            parsed.mitigations.add(value.upper())
        elif CAMPAIGN_PATTERN.fullmatch(value):
            parsed.campaigns.add(value.upper())
        else:
            tactic = catalog.resolve_tactic(value)
            if tactic is not None:
                parsed.explicit_tactics.add(tactic)
            else:
                parsed.unknown_attack_tags.add(value)
    return parsed


def _load_documents(path: Path) -> list[Mapping[str, Any]]:
    try:
        with path.open(encoding="utf-8") as handle:
            documents = [doc for doc in yaml.safe_load_all(handle) if doc is not None]
    except (OSError, yaml.YAMLError) as exc:
        raise RuleMappingError(f"Unable to load Sigma rule {path}: {exc}") from exc
    if not documents:
        raise RuleMappingError(f"Sigma rule {path} is empty")
    for document in documents:
        if not isinstance(document, Mapping):
            raise RuleMappingError(f"Sigma rule {path} must contain a YAML mapping")
    return documents


def _mapping_from_data(
    data: Mapping[str, Any],
    path: str | None,
    catalog: AttackCatalog,
) -> AttackMapping:
    tags = tuple(str(tag) for tag in _tag_strings(data.get("tags") or []))
    parsed = parse_attack_tags(tags, catalog=catalog)
    derived_tactics: set[str] = set()
    for technique_id in parsed.techniques:
        derived_tactics.update(catalog.tactics_for(technique_id))

    return AttackMapping(
        rule_id=str(data["id"]) if data.get("id") is not None else None,
        title=str(data.get("title") or (Path(path).stem if path else "")),
        path=path,
        tags=tags,
        techniques=tuple(sorted(parsed.techniques)),
        explicit_tactics=tuple(sorted(parsed.explicit_tactics)),
        tactics=tuple(sorted(parsed.explicit_tactics | derived_tactics)),
        software=tuple(sorted(parsed.software)),
        groups=tuple(sorted(parsed.groups)),
        data_sources=tuple(sorted(parsed.data_sources)),
        mitigations=tuple(sorted(parsed.mitigations)),
        campaigns=tuple(sorted(parsed.campaigns)),
        unknown_techniques=tuple(sorted(parsed.unknown_techniques)),
        unknown_attack_tags=tuple(sorted(parsed.unknown_attack_tags)),
    )


def map_rule(
    rule: Any,
    path: str | Path | None = None,
    catalog: AttackCatalog | None = None,
) -> AttackMapping:
    """Map a Sigma rule to ATT&CK.

    ``rule`` may be a mapping (for example ``yaml.safe_load`` output), a pySigma
    ``SigmaRule`` instance, or a path to a Sigma YAML file. The function does
    not modify the input rule and only reads the standard ``tags`` metadata, so
    it is safe to use alongside pySigma converters.
    """

    catalog = catalog or get_catalog()
    if isinstance(rule, (str, Path)):
        rule_path = Path(rule)
        documents = _load_documents(rule_path)
        return _mapping_from_data(documents[0], str(rule_path), catalog)

    if isinstance(rule, Mapping):
        label = str(path) if path is not None else None
        return _mapping_from_data(rule, label, catalog)

    if hasattr(rule, "tags"):
        data = {
            "id": getattr(rule, "id", None),
            "title": getattr(rule, "title", None),
            "tags": getattr(rule, "tags", None),
        }
        label = str(path) if path is not None else None
        return _mapping_from_data(data, label, catalog)

    raise TypeError("rule must be a mapping, a pySigma SigmaRule, or a YAML file path")


def iter_rule_files(
    paths: str | Path | Sequence[str | Path],
    file_pattern: str = "*.yml",
) -> Iterable[Path]:
    """Yield rule files from files and directories in deterministic order."""

    if isinstance(paths, (str, Path)):
        paths = [paths]
    seen: set[Path] = set()
    for raw_path in paths:
        path = Path(raw_path)
        if not path.exists():
            raise FileNotFoundError(f"Rule path does not exist: {path}")
        candidates = [path] if path.is_file() else path.rglob(file_pattern)
        for candidate in sorted(candidates):
            if candidate.is_file() and candidate not in seen:
                seen.add(candidate)
                yield candidate


def map_rules(
    paths: str | Path | Sequence[str | Path],
    file_pattern: str = "*.yml",
    catalog: AttackCatalog | None = None,
) -> tuple[AttackMapping, ...]:
    """Map all Sigma YAML documents below one or more files/directories."""

    catalog = catalog or get_catalog()
    mappings: list[AttackMapping] = []
    for rule_path in iter_rule_files(paths, file_pattern=file_pattern):
        documents = _load_documents(rule_path)
        for index, document in enumerate(documents, 1):
            label = str(rule_path)
            if len(documents) > 1:
                label = f"{label}#{index}"
            mappings.append(_mapping_from_data(document, label, catalog))
    return tuple(mappings)


def attack_tags_for(mapping: AttackMapping) -> tuple[str, ...]:
    """Return canonical ``attack.*`` tags for an existing mapping."""

    return tuple(
        sorted(
            [f"attack.{technique.lower()}" for technique in mapping.techniques]
            + [f"attack.{tactic}" for tactic in mapping.tactics]
        )
    )

"""MITRE ATT&CK catalog helpers used by the Sigma ATT&CK mapper."""

from __future__ import annotations

import json
import re
from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path
from typing import Any, Iterable, Mapping


TECHNIQUE_PATTERN = re.compile(r"^t\d{4}(?:\.\d{3})?$", re.IGNORECASE)
TACTIC_PATTERN = re.compile(r"^[a-z][a-z0-9-]*$", re.IGNORECASE)

# ATT&CK renamed "defense-evasion" to "stealth" in ATT&CK v19. Accept both
# spellings so older Sigma rules and custom rule sets keep mapping correctly.
TACTIC_ALIASES = {
    "defence-evasion": "stealth",
    "defense-evasion": "stealth",
}

TACTIC_ORDER = (
    "reconnaissance",
    "resource-development",
    "initial-access",
    "execution",
    "persistence",
    "privilege-escalation",
    "stealth",
    "credential-access",
    "discovery",
    "lateral-movement",
    "collection",
    "command-and-control",
    "exfiltration",
    "impact",
    "defense-impairment",
)

DEFAULT_CATALOG_PATH = Path(__file__).resolve().parent / "data" / "attack_catalog.json"


def normalize_technique(value: str) -> str | None:
    """Return a canonical technique ID (``T1059.001``) or ``None``."""

    value = value.strip().lower()
    if value.startswith("attack."):
        value = value[7:]
    if not TECHNIQUE_PATTERN.fullmatch(value):
        return None
    return value.upper()


def normalize_tactic(value: str) -> str | None:
    """Return a canonical ATT&CK tactic short name or ``None``."""

    value = value.strip().lower()
    if value.startswith("attack."):
        value = value[7:]
    value = re.sub(r"[\s_]+", "-", value)
    value = re.sub(r"-+", "-", value).strip("-")
    if not value or not TACTIC_PATTERN.fullmatch(value):
        return None
    return TACTIC_ALIASES.get(value, value)


@dataclass(frozen=True)
class AttackTechnique:
    """A technique from the bundled ATT&CK catalog."""

    technique_id: str
    name: str
    tactics: tuple[str, ...]
    parent_id: str | None = None

    @property
    def is_subtechnique(self) -> bool:
        return "." in self.technique_id

    def to_dict(self) -> dict[str, Any]:
        return {
            "name": self.name,
            "tactics": list(self.tactics),
            "parent_id": self.parent_id,
        }


class AttackCatalog:
    """Enterprise ATT&CK technique and tactic lookup.

    The catalog is bundled so mapping and reporting are deterministic and do not
    require network access. ``from_stix`` also accepts an official ATT&CK STIX
    bundle, which keeps the data refresh path straightforward.
    """

    def __init__(
        self,
        version: str,
        domain: str,
        tactics: Mapping[str, str],
        techniques: Mapping[str, AttackTechnique],
    ) -> None:
        self.version = version
        self.domain = domain
        self._tactic_names = tuple(dict.fromkeys(tactics.values()))
        self._tactic_by_name = {name: tactic_id for tactic_id, name in tactics.items()}
        self._techniques = dict(techniques)
        self._techniques_by_tactic: dict[str, tuple[str, ...]] = {}
        for tactic in self._tactic_names:
            self._techniques_by_tactic[tactic] = tuple(
                sorted(
                    technique_id
                    for technique_id, technique in self._techniques.items()
                    if tactic in technique.tactics
                )
            )

    @classmethod
    def load(cls, path: str | Path | None = None) -> "AttackCatalog":
        catalog_path = Path(path) if path is not None else DEFAULT_CATALOG_PATH
        with catalog_path.open(encoding="utf-8") as handle:
            return cls.from_dict(json.load(handle))

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> "AttackCatalog":
        techniques: dict[str, AttackTechnique] = {}
        for raw_id, raw in (data.get("techniques") or {}).items():
            technique_id = normalize_technique(str(raw_id))
            if technique_id is None:
                raise ValueError(f"Invalid ATT&CK technique ID in catalog: {raw_id!r}")
            tactics = []
            for raw_tactic in raw.get("tactics") or []:
                tactic = normalize_tactic(str(raw_tactic))
                if tactic is not None and tactic not in tactics:
                    tactics.append(tactic)
            techniques[technique_id] = AttackTechnique(
                technique_id=technique_id,
                name=str(raw.get("name") or technique_id),
                tactics=tuple(tactics),
                parent_id=raw.get("parent"),
            )
        return cls(
            version=str(data.get("version") or "unknown"),
            domain=str(data.get("domain") or "enterprise-attack"),
            tactics={str(k): str(v) for k, v in (data.get("tactics") or {}).items()},
            techniques=techniques,
        )

    @classmethod
    def from_stix(cls, path: str | Path) -> "AttackCatalog":
        """Build a catalog from an ATT&CK enterprise STIX bundle."""

        with Path(path).open(encoding="utf-8") as handle:
            bundle = json.load(handle)

        tactics: dict[str, str] = {}
        techniques: dict[str, AttackTechnique] = {}
        version = "unknown"

        def external_id(obj: Mapping[str, Any]) -> str | None:
            for reference in obj.get("external_references") or []:
                if reference.get("source_name") == "mitre-attack":
                    value = reference.get("external_id")
                    if value:
                        return str(value)
            return None

        for obj in bundle.get("objects") or []:
            if obj.get("revoked") or obj.get("x_mitre_deprecated"):
                continue
            obj_type = obj.get("type")
            if obj_type == "x-mitre-collection":
                version = str(obj.get("x_mitre_version") or version)
            elif obj_type == "x-mitre-tactic":
                tactic_id = external_id(obj)
                shortname = normalize_tactic(str(obj.get("x_mitre_shortname") or ""))
                if tactic_id and shortname:
                    tactics[tactic_id] = shortname
            elif obj_type == "attack-pattern":
                technique_id = external_id(obj)
                if not technique_id:
                    continue
                canonical_id = normalize_technique(technique_id)
                if canonical_id is None:
                    continue
                technique_tactics = []
                for phase in obj.get("kill_chain_phases") or []:
                    if phase.get("kill_chain_name") != "mitre-attack":
                        continue
                    tactic = normalize_tactic(str(phase.get("phase_name") or ""))
                    if tactic is not None and tactic not in technique_tactics:
                        technique_tactics.append(tactic)
                parent_id = (
                    str(obj.get("x_mitre_is_subtechnique"))
                    if obj.get("x_mitre_is_subtechnique") is not None
                    else None
                )
                techniques[canonical_id] = AttackTechnique(
                    technique_id=canonical_id,
                    name=str(obj.get("name") or canonical_id),
                    tactics=tuple(technique_tactics),
                    parent_id=(canonical_id.split(".")[0] if "." in canonical_id else None),
                )
                if parent_id is not None and not obj.get("x_mitre_is_subtechnique"):
                    techniques[canonical_id] = AttackTechnique(
                        technique_id=canonical_id,
                        name=str(obj.get("name") or canonical_id),
                        tactics=tuple(technique_tactics),
                        parent_id=None,
                    )
        return cls(version=version, domain="enterprise-attack", tactics=tactics, techniques=techniques)

    @property
    def tactics(self) -> tuple[str, ...]:
        """Tactic short names in canonical kill-chain order."""

        remaining = set(self._tactic_names)
        ordered = [tactic for tactic in TACTIC_ORDER if tactic in remaining]
        ordered.extend(sorted(remaining.difference(ordered)))
        return tuple(ordered)

    @property
    def techniques(self) -> Mapping[str, AttackTechnique]:
        return dict(self._techniques)

    def technique(self, technique_id: str) -> AttackTechnique | None:
        normalized = normalize_technique(technique_id)
        return self._techniques.get(normalized) if normalized else None

    def is_known_technique(self, technique_id: str) -> bool:
        return self.technique(technique_id) is not None

    def is_known_tactic(self, tactic: str) -> bool:
        normalized = normalize_tactic(tactic)
        return normalized in self._tactic_by_name if normalized else False

    def resolve_tactic(self, value: str) -> str | None:
        normalized = normalize_tactic(value)
        if normalized is None or normalized not in self._tactic_by_name:
            return None
        return normalized

    def tactics_for(self, technique_id: str) -> tuple[str, ...]:
        technique = self.technique(technique_id)
        return technique.tactics if technique else ()

    def techniques_for_tactic(self, tactic: str) -> tuple[str, ...]:
        normalized = self.resolve_tactic(tactic)
        if normalized is None:
            return ()
        return self._techniques_by_tactic.get(normalized, ())

    def iter_techniques(self) -> Iterable[AttackTechnique]:
        return (self._techniques[technique_id] for technique_id in sorted(self._techniques))


@lru_cache(maxsize=1)
def get_catalog() -> AttackCatalog:
    """Return the process-wide default catalog."""

    return AttackCatalog.load()

"""MITRE ATT&CK coverage reports generated from Sigma rule mappings."""

from __future__ import annotations

from collections import Counter, defaultdict
from dataclasses import dataclass
from typing import Any, Iterable, Mapping, Sequence

from .catalog import AttackCatalog, get_catalog
from .mapping import AttackMapping


def _percentage(numerator: int, denominator: int) -> float:
    if denominator == 0:
        return 0.0
    return round(numerator * 100.0 / denominator, 2)


@dataclass(frozen=True)
class TechniqueCoverage:
    technique_id: str
    name: str
    tactics: tuple[str, ...]
    mappings: tuple[AttackMapping, ...]
    known: bool = True

    @property
    def rule_count(self) -> int:
        return len(self.mappings)

    def to_dict(self, include_rule_refs: bool = True) -> dict[str, Any]:
        data: dict[str, Any] = {
            "name": self.name,
            "tactics": list(self.tactics),
            "known": self.known,
            "rule_count": self.rule_count,
        }
        if include_rule_refs:
            data["rules"] = [mapping.rule_ref() for mapping in self.mappings]
        return data


@dataclass(frozen=True)
class TacticCoverage:
    tactic: str
    catalog_techniques: tuple[str, ...]
    covered_techniques: tuple[str, ...]
    rule_count: int

    @property
    def uncovered_techniques(self) -> tuple[str, ...]:
        covered = set(self.covered_techniques)
        return tuple(
            technique
            for technique in self.catalog_techniques
            if technique not in covered
        )

    @property
    def coverage_percent(self) -> float:
        return _percentage(len(self.covered_techniques), len(self.catalog_techniques))

    def to_dict(self) -> dict[str, Any]:
        return {
            "catalog_techniques": len(self.catalog_techniques),
            "covered_techniques": len(self.covered_techniques),
            "coverage_percent": self.coverage_percent,
            "rule_count": self.rule_count,
            "techniques": list(self.covered_techniques),
            "uncovered_techniques": list(self.uncovered_techniques),
        }


class CoverageReport:
    """Aggregated ATT&CK coverage for a set of Sigma rules."""

    def __init__(
        self,
        mappings: Iterable[AttackMapping],
        catalog: AttackCatalog | None = None,
    ) -> None:
        self.catalog = catalog or get_catalog()
        self.mappings = tuple(mappings)

        technique_mappings: dict[str, list[AttackMapping]] = defaultdict(list)
        for mapping in self.mappings:
            for technique_id in mapping.techniques:
                technique_mappings[technique_id].append(mapping)

        self._by_technique: dict[str, TechniqueCoverage] = {}
        for technique_id in sorted(technique_mappings):
            technique = self.catalog.technique(technique_id)
            self._by_technique[technique_id] = TechniqueCoverage(
                technique_id=technique_id,
                name=technique.name if technique else technique_id,
                tactics=technique.tactics if technique else (),
                mappings=tuple(technique_mappings[technique_id]),
                known=technique is not None,
            )

        tactic_rule_counts: Counter[str] = Counter()
        for mapping in self.mappings:
            tactic_rule_counts.update(set(mapping.tactics))

        self._by_tactic: dict[str, TacticCoverage] = {}
        for tactic in self.catalog.tactics:
            catalog_techniques = self.catalog.techniques_for_tactic(tactic)
            covered = tuple(
                technique_id
                for technique_id in catalog_techniques
                if technique_id in self._by_technique
            )
            self._by_tactic[tactic] = TacticCoverage(
                tactic=tactic,
                catalog_techniques=catalog_techniques,
                covered_techniques=covered,
                rule_count=tactic_rule_counts.get(tactic, 0),
            )

    @property
    def by_technique(self) -> Mapping[str, TechniqueCoverage]:
        return dict(self._by_technique)

    @property
    def by_tactic(self) -> Mapping[str, TacticCoverage]:
        return dict(self._by_tactic)

    @property
    def rules_with_techniques(self) -> tuple[AttackMapping, ...]:
        return tuple(mapping for mapping in self.mappings if mapping.techniques)

    @property
    def rules_without_technique(self) -> tuple[AttackMapping, ...]:
        return tuple(mapping for mapping in self.mappings if not mapping.techniques)

    @property
    def rules_without_any_attack_mapping(self) -> tuple[AttackMapping, ...]:
        return tuple(mapping for mapping in self.mappings if not mapping.is_mapped)

    @property
    def unknown_techniques(self) -> tuple[str, ...]:
        return tuple(
            technique_id
            for technique_id, coverage in self._by_technique.items()
            if not coverage.known
        )

    @property
    def unknown_attack_tags(self) -> Mapping[str, tuple[AttackMapping, ...]]:
        references: dict[str, list[AttackMapping]] = defaultdict(list)
        for mapping in self.mappings:
            for tag in mapping.unknown_attack_tags:
                references[tag].append(mapping)
        return {tag: tuple(references[tag]) for tag in sorted(references)}

    def summary(self) -> dict[str, Any]:
        total = len(self.mappings)
        with_technique = len(self.rules_with_techniques)
        with_tactic = sum(1 for mapping in self.mappings if mapping.tactics)
        catalog_techniques = len(self.catalog.techniques)
        return {
            "rules_total": total,
            "rules_with_attack_technique": with_technique,
            "rules_with_attack_tactic": with_tactic,
            "rules_without_technique": len(self.rules_without_technique),
            "rules_without_any_attack_mapping": len(self.rules_without_any_attack_mapping),
            "rule_coverage_percent": _percentage(with_technique, total),
            "techniques_covered": len(self._by_technique),
            "techniques_in_catalog": catalog_techniques,
            "technique_coverage_percent": _percentage(
                len(self._by_technique), catalog_techniques
            ),
            "techniques_unknown": len(self.unknown_techniques),
            "unknown_attack_tags": len(self.unknown_attack_tags),
        }

    def to_dict(self, include_rule_refs: bool = True) -> dict[str, Any]:
        summary = self.summary()
        return {
            "attack_version": self.catalog.version,
            "domain": self.catalog.domain,
            "summary": summary,
            "by_tactic": {
                tactic: coverage.to_dict()
                for tactic, coverage in self._by_tactic.items()
            },
            "by_technique": {
                technique_id: coverage.to_dict(include_rule_refs=include_rule_refs)
                for technique_id, coverage in self._by_technique.items()
            },
            "unknown_techniques": list(self.unknown_techniques),
            "unknown_attack_tags": [
                {
                    "tag": f"attack.{tag}",
                    "rule_count": len(mappings),
                    "rules": [mapping.rule_ref() for mapping in mappings],
                }
                for tag, mappings in self.unknown_attack_tags.items()
            ],
            "rules_without_technique": [
                mapping.rule_ref() for mapping in self.rules_without_technique
            ],
        }

    def to_markdown(
        self,
        max_unmapped: int = 50,
        top_techniques: int = 20,
        uncovered_examples: int = 12,
        include_rule_refs: bool = True,
    ) -> str:
        summary = self.summary()
        lines = [
            "# MITRE ATT&CK Coverage Report",
            "",
            f"- ATT&CK version: {self.catalog.version}",
            f"- Rules scanned: {summary['rules_total']}",
            (
                "- Rules with ATT&CK techniques: "
                f"{summary['rules_with_attack_technique']} "
                f"({summary['rule_coverage_percent']:.2f}%)"
            ),
            f"- Rules with ATT&CK tactics: {summary['rules_with_attack_tactic']}",
            f"- Rules without a technique: {summary['rules_without_technique']}",
            (
                "- Techniques covered: "
                f"{summary['techniques_covered']}/{summary['techniques_in_catalog']} "
                f"({summary['technique_coverage_percent']:.2f}%)"
            ),
            "",
            "## Coverage by tactic",
            "",
            "| Tactic | Covered | Total | Coverage | Rules |",
            "| --- | ---: | ---: | ---: | ---: |",
        ]
        for coverage in self._by_tactic.values():
            lines.append(
                f"| {coverage.tactic} | {len(coverage.covered_techniques)} | "
                f"{len(coverage.catalog_techniques)} | "
                f"{coverage.coverage_percent:.2f}% | {coverage.rule_count} |"
            )

        ranked = sorted(
            self._by_technique.values(),
            key=lambda coverage: (-coverage.rule_count, coverage.technique_id),
        )
        if top_techniques > 0 and ranked:
            lines.extend(
                [
                    "",
                    "## Top covered techniques",
                    "",
                    "| Technique | Name | Tactic | Rules |",
                    "| --- | --- | --- | ---: |",
                ]
            )
            for coverage in ranked[:top_techniques]:
                tactics = ", ".join(coverage.tactics) or "unknown"
                lines.append(
                    f"| {coverage.technique_id} | {self._escape(coverage.name)} | "
                    f"{tactics} | {coverage.rule_count} |"
                )

        uncovered = [coverage for coverage in self._by_tactic.values() if coverage.uncovered_techniques]
        if uncovered_examples > 0 and uncovered:
            lines.extend(
                [
                    "",
                    "## Uncovered techniques by tactic",
                    "",
                    "| Tactic | Uncovered | Examples |",
                    "| --- | ---: | --- |",
                ]
            )
            for coverage in uncovered:
                examples = ", ".join(
                    coverage.uncovered_techniques[:uncovered_examples]
                )
                if len(coverage.uncovered_techniques) > uncovered_examples:
                    examples += ", ..."
                lines.append(
                    f"| {coverage.tactic} | "
                    f"{len(coverage.uncovered_techniques)} | {examples} |"
                )

        if include_rule_refs and self.rules_without_technique and max_unmapped > 0:
            lines.extend(["", "## Rules without a technique", ""])
            for mapping in self.rules_without_technique[:max_unmapped]:
                label = mapping.path or mapping.title or mapping.rule_id or "<unknown rule>"
                if mapping.title and mapping.path:
                    label = f"{label} ({mapping.title})"
                lines.append(f"- `{label}`")
            remaining = len(self.rules_without_technique) - min(
                max_unmapped, len(self.rules_without_technique)
            )
            if remaining > 0:
                lines.append(f"- ... and {remaining} more")

        if self.unknown_attack_tags:
            lines.extend(["", "## Unknown ATT&CK tags", ""])
            for tag, mappings in self.unknown_attack_tags.items():
                lines.append(f"- `attack.{tag}` ({len(mappings)} rules)")

        lines.append("")
        return "\n".join(lines)

    def to_navigator_layer(
        self,
        name: str = "Sigma ATT&CK Coverage",
        description: str | None = None,
        min_score: int = 0,
        max_score: int | None = None,
        min_color: str = "#ffffff00",
        max_color: str = "#ff0000",
        include_subtechniques: bool = True,
    ) -> dict[str, Any]:
        scores: Counter[str] = Counter()
        for mapping in self.mappings:
            for technique_id in mapping.techniques:
                if not include_subtechniques:
                    technique_id = technique_id.split(".")[0]
                scores[technique_id] += 1

        techniques: list[dict[str, Any]] = []
        for technique_id in sorted(scores):
            for tactic in self.catalog.tactics_for(technique_id):
                techniques.append(
                    {
                        "techniqueID": technique_id,
                        "tactic": tactic,
                        "score": scores[technique_id],
                        "color": "",
                        "comment": "",
                        "enabled": True,
                        "metadata": [],
                        "links": [],
                        "showSubtechniques": False,
                    }
                )

        highest_score = max_score if max_score is not None else max(scores.values(), default=0)
        return {
            "name": name,
            "versions": {
                "attack": self.catalog.version,
                "navigator": "4.8.1",
                "layer": "4.4",
            },
            "domain": self.catalog.domain,
            "description": description
            or "Sigma ATT&CK coverage generated by sigma_attack",
            "gradient": {
                "colors": [min_color, max_color],
                "minValue": min_score,
                "maxValue": highest_score,
            },
            "techniques": techniques,
        }

    @staticmethod
    def _escape(value: str) -> str:
        return value.replace("|", "\\|").replace("\n", " ")


def build_coverage(
    mappings: Iterable[AttackMapping],
    catalog: AttackCatalog | None = None,
) -> CoverageReport:
    """Build a coverage report from ATT&CK mappings."""

    return CoverageReport(mappings, catalog=catalog)

from .cli import main


if __name__ == "__main__":
    raise SystemExit(main())

